index f29e607..78c6b85 100644
--- a/src/llama-vocab.cpp
+++ b/src/llama-vocab.cpp
@@ -2482,6 +2482,14 @@ void llama_vocab::impl::load(llama_model_loader & ml, const LLM_KV & kv) {
             LLAMA_LOG_WARN("%s: special_eom_id is not in special_eog_ids - the tokenizer config may be incorrect\n", __func__);
         }

+        // HyperCLOVA thinking ends a message before starting the final assistant message.
+        if (ml.get_arch() == LLM_ARCH_HCX_SEED_THINK) {
+            special_eog_ids.erase(token_to_id.at("<|im_end|>"));
+            special_eot_id = token_to_id.at("<|endofturn|>");
+            special_eog_ids.insert(special_eot_id);
+            special_eog_ids.insert(token_to_id.at("<|stop|>"));
+        }
+
         // TODO: workaround for o200k_harmony and solar-open tokenizer: the "<|end|>" token should not be EOG
         //       we don't have a good way to detect this, so for now, if we have "<|return|>" and "<|call|>" tokens ("<|calls|>" and "<|flush|>" for solar-open),
         //       we remove the "<|end|>" token from the EOG list

